# Teresa is 59 and her husband Morio is 71 years old. Their daughter, Michiko was born when Morio was 38.  How old was Teresa when she gave birth to Michiko?
program GSM7389 implements ISolver {
    type Input = str;
    type Output = quantity;
    @external
    public function parse(raw: str): Input { return raw; }

    public pure function verify(input: Input, output: Output): bool { return true; }



    @external
    public function solve(input: Input): Output {
        create s0 : quantity;   # step 0: 71 - 59 = 12
        assign s0 = 71;
        sub s0, 59;
        create s1 : quantity;   # step 1: 38 - 12 = 26
        assign s1 = 38;
        sub s1, s0;
        sum s1;
        query s1;
        return s1;
    }
}

# Ellis is going to take a road trip with her family. First, she needs to figure out how many bottles of water she should bring for everyone. There will be four people total: Ellis, her mother, her sister, and her aunt. They will be on the road to their destination for 8 hours and drive 8 hours to return home. Every hour each person will want to drink 1/2 a bottle of water. How many water bottles will Ellis' family need total?
program GSM6024 implements ISolver {
    type Input = str;
    type Output = quantity;
    @external
    public function parse(raw: str): Input { return raw; }

    public pure function verify(input: Input, output: Output): bool { return true; }



    @external
    public function solve(input: Input): Output {
        create s0 : quantity;   # step 0: 8 + 8 = 16
        assign s0 = 8;
        add s0, 8;
        create s1 : quantity;   # step 1: 1 / 2 = 0.5
        assign s1 = 1;
        div s1, 2;
        create s2 : quantity;   # step 2: 0.5 * 16 = 8
        assign s2 = 0;
        add s2, s1;
        mul s2, s0;
        create s3 : quantity;   # step 3: 8 * 4 = 32
        assign s3 = 0;
        add s3, s2;
        mul s3, 4;
        sum s3;
        query s3;
        return s3;
    }
}

