# Two paths to the pellet take 12 and 5 steps; report the shorter one.
program Cmp0 implements ISolver {
    type Input = quantity;
    type Output = quantity;

    storage {
        comparisons_made: mutable u64 = 0;
        last_winner: mutable str = "";
    }

    @system @once
    public function constructor() {
        assign comparisons_made = 0;
        assign last_winner = "none";
    }

    @external
    public function parse(raw: str): Input { return raw; }

    @external
    public function solve(input: Input): Output {
        create lhs : quantity;
        assign lhs = 12;
        store lhs, "candidate_left";
        create rhs : quantity;
        assign rhs = 5;
        store rhs, "candidate_right";
        create result : quantity;
        assign result = 0;
        if (lhs > rhs) {
            add result, rhs;
            assign last_winner = "right";
        } else {
            add result, lhs;
            assign last_winner = "left";
        }
        store result, "selected_min";
        query result;
        remember result;
        add comparisons_made, 1;
        sum result;
        return result;
    }

    @external
    public pure function verify(input: Input, output: Output): bool { return true; }
}

# A ghost is 10 cells away; sound the alarm if the alarm level 2 exceeds that distance.
program Dec0 implements ISolver {
    type Input = quantity;
    type Output = quantity;

    storage {
        threshold: mutable u64 = 0;
        decisions_made: mutable u64 = 0;
        last_decision: mutable str = "";
    }

    @system @once
    public function constructor() {
        assign threshold = 10;
        assign decisions_made = 0;
        assign last_decision = "none";
    }

    @external
    public function parse(raw: str): Input { return raw; }

    @external
    public function solve(input: Input): Output {
        create observation : quantity;
        assign observation = 2;
        store observation, "current_observation";
        create gate_value : quantity;
        assign gate_value = 10;
        store gate_value, "gate_threshold";
        create confidence : quantity;
        assign confidence = 0;
        if (observation > gate_value) {
            add confidence, 90;
            assign last_decision = "flee";
            store confidence, "flee_confidence";
        } else {
            add confidence, 30;
            assign last_decision = "stay";
            store confidence, "stay_confidence";
        }
        query confidence;
        remember confidence;
        add decisions_made, 1;
        sum confidence;
        return confidence;
    }

    @external
    public pure function verify(input: Input, output: Output): bool { return true; }
}

